<?php $pageTitle='Scoring Control';require_once dirname(__DIR__).'/includes/header.php';require_once dirname(__DIR__).'/includes/auth.php';require_auth();$t=active_tournament($pdo);$tid=(int)($t['id']??0);$sql="SELECT m.id,m.round,m.status,p1.name p1_name,p2.name p2_name FROM matches m LEFT JOIN participants p1 ON p1.id=m.participant1_id LEFT JOIN participants p2 ON p2.id=m.participant2_id WHERE m.tournament_id=?";$params=[$tid];if($_SESSION['user']['role']==='judge'){$sql.=' AND m.assigned_judge_id=?';$params[]=$_SESSION['user']['id'];}$sql.=" AND m.status<>'finished' ORDER BY FIELD(m.status,'live','paused','scheduled'),m.round_number,m.match_number";$s=$pdo->prepare($sql);$s->execute($params);$matches=$s->fetchAll();$selected=(int)($_GET['match_id']??($matches[0]['id']??0));require dirname(__DIR__).'/includes/sidebar.php';?>
<section class="scoring-panel"><div class="toolbar"><div><div class="eyebrow">Fast match control</div><h2 style="margin:4px 0">Live scoring</h2></div><div style="min-width:280px"><label>Select Match</label><select id="match-select"><?php foreach($matches as $m):?><option value="<?=$m['id']?>" <?=$selected===$m['id']?'selected':''?>>#<?=$m['id']?> · <?=e($m['p1_name']??'TBD')?> vs <?=e($m['p2_name']??'TBD')?> (<?=e($m['status'])?>)</option><?php endforeach;?></select></div></div><?php if(!$matches):?><div class="card empty"><i class="fa-solid fa-stopwatch"></i><h3>No scoreable matches</h3><p>Assign a scheduled or live match to this account.</p></div><?php else:?><div class="card"><div style="text-align:center;margin-bottom:22px"><span id="score-status" class="badge live">LOADING</span></div><div class="scoring-grid"><div class="scoring-team"><h2 id="team1-name">Team 1</h2><div id="score1" class="giant-score">00</div><div class="score-controls"><button class="score-btn score-action" data-slot="1" data-score="-1">−1</button><button class="score-btn plus score-action" data-slot="1" data-score="1">+1</button></div><div class="inline-actions" style="margin-top:10px"><input id="set-score-1" type="number" min="0" max="999" placeholder="Set score"><button class="btn" data-set-score="1">Set</button></div></div><strong>VS</strong><div class="scoring-team"><h2 id="team2-name">Team 2</h2><div id="score2" class="giant-score">00</div><div class="score-controls"><button class="score-btn score-action" data-slot="2" data-score="-1">−1</button><button class="score-btn plus score-action" data-slot="2" data-score="1">+1</button></div><div class="inline-actions" style="margin-top:10px"><input id="set-score-2" type="number" min="0" max="999" placeholder="Set score"><button class="btn" data-set-score="2">Set</button></div></div></div><div class="scoring-actions"><button class="btn btn-primary" data-match-action="start"><i class="fa-solid fa-play"></i> START MATCH</button><button class="btn" data-match-action="pause"><i class="fa-solid fa-pause"></i> PAUSE</button><button class="btn btn-danger" data-match-action="finish"><i class="fa-solid fa-flag-checkered"></i> FINISH MATCH</button><button class="btn btn-ghost" data-match-action="reset"><i class="fa-solid fa-rotate-left"></i> RESET SCORE</button></div><div class="last-updated">Last Updated: <span id="last-updated">—</span></div></div><?php endif;?></section><script defer src="<?=BASE_URL?>/assets/js/scoring.js"></script>
